WITH item_returns AS ( SELECT i.i_item_id, i.i_category, ib.ib_lower_bound, ib.ib_upper_bound, SUM(cr.cr_return_quantity) AS total_return_qty, SUM(cr.cr_return_amount) AS total_return_amount, SUM(cr.cr_net_loss) AS total_net_loss FROM catalog_returns cr JOIN item i ON cr.cr_item_sk = i.i_item_sk JOIN household_demographics hd ON cr.cr_returning_hdemo_sk = hd.hd_demo_sk JOIN income_band ib ON hd.hd_income_band_sk = ib.ib_income_band_sk GROUP BY i.i_item_id, i.i_category, ib.ib_lower_bound, ib.ib_upper_bound ) SELECT i_item_id, i_category, ib_lower_bound, ib_upper_bound, total_return_qty, total_return_amount, total_net_loss, CASE WHEN total_net_loss > 10000 THEN 'High' ELSE 'Low' END AS net_loss_category, RANK() OVER (ORDER BY total_net_loss DESC) AS net_loss_rank FROM item_returns ORDER BY net_loss_rank
